function addBonus(scores) {
  let result = [];
  for (let s of scores) {
    result.push(s + 5);
  }
  return result;
}

let marks = [70, 80];
let bumped = addBonus(marks);

console.log(marks[0], bumped[0]);

function smallestOf(numbers) {
  let best = 0;
  for (let n of numbers) {
    if (n < best) {
      best = n;
    }
  }
  return best;
}

console.log(smallestOf([4, 9, 6]));

